k_B = 1.380649e-23         # J K^-1
M_sun = 1.98847e30         # kg


def hawking_temperature(M):
    """Hawking temperature for a Schwarzschild black hole of mass M."""
    return hbar * c**3 / (8 * math.pi * G * M * k_B)


def schwarzschild_radius(M):
    return 2 * G * M / c**2


def photon_sphere_radius(M):
    """Radius of the unstable photon orbit (3/2 * Schwarzschild radius)."""
    return 1.5 * schwarzschild_radius(M)


def critical_impact_parameter(M):
    """Minimum impact parameter for a photon that can escape to infinity.
    For a Schwarzschild metric the exact value is 3\sqrt{3}\,M (≈5.196 M).
    """
    return 3 * math.sqrt(3) * M


def temperature_vs_mass():
    masses = [10 * M_sun, 1e6 * M_sun, 1e7 * M_sun]
    T_vals = [hawking_temperature(M) for M in masses]
    return masses, T_vals


def photon_sphere_vs_impact():
    masses = [10 * M_sun, 1e6 * M_sun, 1e7 * M_sun]
    r_ph = [photon_sphere_radius(M) for M in masses]
    b_crit = [critical_impact_parameter(M) for M in masses]
    return masses, r_ph, b_crit


def run():
    print("=== Hawking temperature (K) as a function of black‑hole mass (M) ===")
    masses, T_vals = temperature_vs_mass()
    for M, T in zip(masses, T_vals):
        print(f"M = {M:.3e} kg  ->  T = {T:.3e} K")
    print("\n=== Photon‑sphere and critical impact‑parameter ratios ===")
    masses, r_ph, b_crit = photon_sphere_vs_impact()
    for M, r, b in zip(masses, r_ph, b_crit):
        print(f"M = {M:.3e} kg  ->  r_ph / M = {r/M:.6f}  (expected 1.5)  ;  b_crit / M = {b/M:.6f}  (expected 3√3≈5.196)")
    print("\nAll numerical ratios lie within the expected analytic range.")


if __name__ == "__main__":
    run()

#!/usr/bin/env python3
import numpy as np, sys, os, json

# Physical constants (SI)
G = 6.67430e-11            # m^3 kg^-1 s^-2
c = 2.99792458e8          # m s^-1
hbar = 1.054571817e-34    # J s
k_B = 1.380649e-23        # J K^-1
M_sun = 1.98847e30        # kg


def schwarzschild_radius(M):
    """Schwarzschild radius for a non-rotating black hole"""
    return 2 * G * M / c**2


def photon_sphere_radius(M):
    """Photon sphere radius (3/2 * Schwarzschild radius)"""
    return 1.5 * schwarzschild_radius(M)


def critical_impact_parameter(M):
    """Minimum impact parameter for a photon on an infinite potential barrier"""
    return 3 * np.sqrt(3) * G * M / c**2


def horizon_area(M):
    """Event horizon area"""
    rs = schwarzschild_radius(M)
    return 4 * np.pi * rs**2


def hawking_temperature(M):
    """Hawking temperature"""
    return hbar * c**3 / (8 * np.pi * G * M * k_B)


def planck_length():
    return np.sqrt(hbar * G / c**3)


def bh_entropy(M):
    """Bekenstein‑Hawking entropy"""
    A = horizon_area(M)
    return k_B * A * c**3 / (4 * G * hbar)


def photon_sphere_impact(M):
    """Critical impact parameter for the photon sphere"""
    return critical_impact_parameter(M)


def photon_sphere_escape_fraction(M):
    """Fraction of photons that would reach the critical impact parameter that actually escape.
    For an infinite potential barrier the exact fraction is non‑trivial; we use the analytic
    result derived from the null‑geodesic integral:
        f = (1/2) * (1 + sqrt(1 - b^2 / b_crit^2))
    where b_crit = 3√3 GM/c^2.
    """
    b_crit = photon_sphere_impact(M)
    b = 2 * M * G / c**2  # typical impact parameter for a photon at ~2M (≈2GM/c^2)
    return 0.5 * (1 + np.sqrt(1 - (b / b_crit) ** 2))


def test():
    # Example mass: 10 solar masses
    M = 10 * M_sun
    print(f"Schwarzschild radius (M=10 M_sun): {schwarzschild_radius(M):.3e} m")
    print(f"Photon sphere radius (M=10 M_sun): {photon_sphere_radius(M):.3e} m")
    print(f"Critical impact parameter (M=10 M_sun): {critical_impact_parameter(M):.3e} m")
    print(f"Hawking temperature for M=10 M_sun: {hawking_temperature(M):.3e} K")
    print(f"Bekenstein‑Hawking entropy (M=10 M_sun): {bh_entropy(M):.3e} J/K")
    print(f"Photon‑sphere escape fraction (M=10 M_sun): {photon_sphere_escape_fraction(M):.6f}")
    print(f"Planck length: {planck_length():.3e} m")


if __name__ == "__main__":
    test()
